    10	public class MessagePipeline {
    11	    public static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    12	    public static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";
    13	
    14	    private final List<MessageRule> rules;
