    18	        this.rules = rules;
    19	        this.testMode = testMode;
    20	    }
    21	
    22	    public static MessagePipeline standard(boolean testMode) {
    23	        return new MessagePipeline(List.of(
    24	                new InvalidAddressRule(),
    25	                new TestRedirectRule(TEST_ADDRESS),
    26	                new ArchiveCopyRule(ARCHIVE_ADDRESS)), testMode);
    27	    }
    28	
    29	    public List<Message> process(Message message) {
    30	        List<Message> current = List.of(message);
    31	        for (MessageRule rule : rules) {
    32	            if (!rule.scope().appliesIn(testMode)) {
    33	                continue;
    34	            }
    35	            List<Message> next = new ArrayList<>();
    36	            for (Message m : current) {
