     6	import java.time.LocalDate;
     7	import java.time.format.DateTimeParseException;
     8	
     9	/** Pedido de reserva já validado quanto ao formato. */
    10	public record BookingRequest(int roomNumber, String guestName, String guestEmail, String guestCpf,
    11	                             LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    12	
    13	    private static final ObjectMapper MAPPER = new ObjectMapper();
    14	
    15	    public static BookingRequest parse(String json) {
    16	        JsonNode root;
    17	        try {
    18	            root = MAPPER.readTree(json);
    19	        } catch (Exception e) {
    20	            throw ApiException.invalid("O corpo não é um JSON válido");
    21	        }
    22	        if (root == null || !root.isObject()) {
    23	            throw ApiException.invalid("O corpo deve ser um objeto JSON");
    24	        }
    25	        LocalDate checkIn = date(root, "checkIn");
    26	        LocalDate checkOut = date(root, "checkOut");
    27	        BookingRequest request = new BookingRequest(
    28	                integer(root, "roomNumber"), text(root, "guestName"), text(root, "guestEmail"),
    29	                text(root, "guestCpf"), checkIn, checkOut, integer(root, "guests"), ratePlan(root));
    30	        if (!checkOut.isAfter(checkIn)) {
    31	            throw ApiException.invalid("A saída deve ser depois da entrada");
    32	        }
    33	        if (request.guests < 1) {
    34	            throw ApiException.invalid("É preciso pelo menos um hóspede");
    35	        }
    36	        return request;
    37	    }
    38	
    39	    private static String text(JsonNode root, String field) {
    40	        JsonNode node = root.get(field);
    41	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    42	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
    43	        }
    44	        return node.asText();
    45	    }
    46	
    47	    private static int integer(JsonNode root, String field) {
    48	        JsonNode node = root.get(field);
    49	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    50	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
    51	        }
    52	        return node.asInt();
    53	    }
    54	
    55	    private static LocalDate date(JsonNode root, String field) {
    56	        try {
    57	            return LocalDate.parse(text(root, field));
    58	        } catch (DateTimeParseException e) {
    59	            throw ApiException.invalid("Data inválida em " + field + " (use AAAA-MM-DD)");
    60	        }
    61	    }
    62	
    63	    private static RatePlan ratePlan(JsonNode root) {
    64	        try {
    65	            return RatePlan.valueOf(text(root, "ratePlan"));
    66	        } catch (IllegalArgumentException e) {
    67	            throw ApiException.invalid("Plano de tarifa inválido");
    68	        }
    69	    }
    70	}
