    11	
    12	    private Pricing() {
    13	    }
    14	
    15	    public static boolean isHighSeason(LocalDate night) {
    16	        Month month = night.getMonth();
    17	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    18	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    19	    }
    20	
    21	    public static BigDecimal nightPrice(RoomType type, LocalDate night) {
    22	        BigDecimal rate = type.nightlyRate;
    23	        return round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    24	    }
    25	
    26	    /** Soma das noites de [checkIn, checkOut). */
    27	    public static BigDecimal subtotal(RoomType type, LocalDate checkIn, LocalDate checkOut) {
    28	        BigDecimal sum = round(BigDecimal.ZERO);
    29	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    30	            sum = round(sum.add(nightPrice(type, night)));
    31	        }
    32	        return sum;
    33	    }
    34	}
